Lemma art_zone_lt_HI : forall FSG rn (G : art_gs FSG) LB (Mr : word -> option byte) x,
  art_alloc_rep FSG rn G LB Mr ->
  (forall p, In p (art_live (g_log FSG G)) -> 0 < fst p /\ 0 < snd p /\ fst p + snd p <= rn_HI rn) ->
